// Skin and champion RP prices for the account value calculator.
// The table is generated by scripts/skin-prices.mjs from community data.
import table from "./data/skin-prices.json";
import type { OwnedChampion, OwnedSkin } from "./api";

const skins = table.skins as Record<string, number | "special">;
const champions = table.champions as Record<string, number>;

/** Typical price per rarity, for skins newer than the bundled table. */
const RARITY_ESTIMATE: Record<string, number> = {
  epic: 1350,
  legendary: 1820,
  ultimate: 3250,
};

export const pricesUpdated: string = table.updated;

export type SkinPrice =
  /** A known RP price. */
  | { kind: "rp"; rp: number }
  /** Not in the table: estimated from the rarity. */
  | { kind: "estimate"; rp: number }
  /** Never sold for RP (Prestige, rewards, event-only, ...). */
  | { kind: "special" }
  /** Not in the table and no rarity to estimate from. */
  | { kind: "unknown" };

export function skinPrice(skin: Pick<OwnedSkin, "id" | "rarity">): SkinPrice {
  const known = skins[String(skin.id)];
  if (known === "special") return { kind: "special" };
  if (typeof known === "number") return { kind: "rp", rp: known };
  if (skin.rarity === "mythic" || skin.rarity === "transcendent" || skin.rarity === "exalted") return { kind: "special" };
  const estimate = RARITY_ESTIMATE[skin.rarity];
  return estimate ? { kind: "estimate", rp: estimate } : { kind: "unknown" };
}

/** RP value of a set of skins (special and unknown ones count as 0). */
export function skinsValue(skins: Pick<OwnedSkin, "id" | "rarity">[]): number {
  return skins.reduce((sum, skin) => {
    const price = skinPrice(skin);
    return sum + (price.kind === "rp" || price.kind === "estimate" ? price.rp : 0);
  }, 0);
}

export const championPrice = (id: number): number => champions[String(id)] ?? 0;

export interface ChampionValue {
  champion: OwnedChampion;
  rp: number;
  special: number;
}

export interface AccountValue {
  skinsRp: number;
  skinCount: number;
  specialCount: number;
  /** Skins counted at a rarity estimate or not priced at all. */
  estimatedCount: number;
  unknownCount: number;
  championsRp: number;
  byChampion: ChampionValue[];
}

export function accountValue(owned: OwnedChampion[]): AccountValue {
  const value: AccountValue = {
    skinsRp: 0,
    skinCount: 0,
    specialCount: 0,
    estimatedCount: 0,
    unknownCount: 0,
    championsRp: 0,
    byChampion: [],
  };
  for (const champion of owned) {
    value.championsRp += championPrice(champion.id);
    const entry: ChampionValue = { champion, rp: 0, special: 0 };
    for (const skin of champion.skins) {
      value.skinCount++;
      const price = skinPrice(skin);
      if (price.kind === "rp" || price.kind === "estimate") {
        entry.rp += price.rp;
        if (price.kind === "estimate") value.estimatedCount++;
      } else if (price.kind === "special") {
        entry.special++;
      } else {
        value.unknownCount++;
      }
    }
    value.skinsRp += entry.rp;
    value.specialCount += entry.special;
    if (champion.skins.length) value.byChampion.push(entry);
  }
  value.byChampion.sort((a, b) => b.rp - a.rp || b.champion.skins.length - a.champion.skins.length);
  return value;
}
